<?php

namespace App\Support;

class Icons
{
    /**
     * @return array{viewBox: string, fill: string, inner: string}|null
     */
    public static function resolve(string $name, bool $outline = false): ?array
    {
        $icons = self::definitions();
        $name = self::aliases()[$name] ?? $name;

        if (str_ends_with($name, '-outline')) {
            return $icons[$name] ?? null;
        }

        $outlineKey = "{$name}-outline";

        if ($outline) {
            return $icons[$outlineKey] ?? $icons[$name] ?? null;
        }

        return $icons[$name] ?? $icons[$outlineKey] ?? null;
    }

    /**
     * @return array<string, string>
     */
    public static function aliases(): array
    {
        return [
            'menu' => 'menu-burger',
            'hamburger' => 'menu-burger',
            'bars' => 'menu-burger',
            'nfc' => 'degrees-360',
            'users' => 'users-alt',
