    /**
     * @return array{viewBox: string, fill: string, inner: string}
     */
    private static function solid(string $viewBox, string $inner): array
    {
        return [
            'viewBox' => $viewBox,
            'fill' => 'currentColor',
            'inner' => $inner,
        ];
    }

    /**
     * @return array{viewBox: string, fill: string, inner: string}
     */
    private static function outline(string $viewBox, string $inner): array
    {
        return [
            'viewBox' => $viewBox,
            'fill' => 'none',
            'inner' => $inner,
        ];
    }

    private static function stroke(string $d): string
    {
        return '<path stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="'.$d.'"/>';
    }
}
